using Payments;

namespace PaymentGateway.Tests;

[TestClass]
public sealed class PaymentGatewayChargeTests
{
    private readonly Payments.PaymentGateway _gateway;

    public PaymentGatewayChargeTests()
    {
        _gateway = new Payments.PaymentGateway();
    }

    [TestMethod]
    public async Task ChargeAsync_ValidCardAndAmount_ReturnsSuccessResult()
    {
        // Arrange
        var cardToken = "tok_valid_visa";
        var amount = 49.99m;

        // Act
        var result = await _gateway.ChargeAsync(cardToken, amount);

        // Assert
        Assert.IsNotNull(result);
        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.ChargeId);
    }

    [TestMethod]
    [DataRow("tok_visa", 1.00)]
    [DataRow("tok_mastercard", 999.99)]
    [DataRow("tok_amex", 0.50)]
    public async Task ChargeAsync_VariousValidCards_ReturnsSuccess(string cardToken, double amount)
    {
        // Act
        var result = await _gateway.ChargeAsync(cardToken, (decimal)amount);

        // Assert
        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_ZeroAmount_ThrowsArgumentException()
    {
        // Arrange
        var cardToken = "tok_valid";

        // Act & Assert
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(cardToken, 0m));
    }

    [TestMethod]
    public async Task ChargeAsync_NegativeAmount_ThrowsArgumentException()
    {
        // Arrange
        var cardToken = "tok_valid";

        // Act & Assert
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(cardToken, -10.00m));
    }

    [TestMethod]
    public async Task ChargeAsync_NullCardToken_ThrowsArgumentNullException()
    {
        // Act & Assert
        await Assert.ThrowsExactlyAsync<ArgumentNullException>(
            async () => await _gateway.ChargeAsync(null!, 25.00m));
    }

    [TestMethod]
    public async Task ChargeAsync_EmptyCardToken_ThrowsArgumentException()
    {
        // Act & Assert
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(string.Empty, 25.00m));
    }

    [TestMethod]
    public async Task ChargeAsync_DeclinedCard_ReturnsFailureResult()
    {
        // Arrange
        var cardToken = "tok_declined";

        // Act
        var result = await _gateway.ChargeAsync(cardToken, 100.00m);

        // Assert
        Assert.IsNotNull(result);
        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_SuccessfulCharge_ReturnsUniqueChargeId()
    {
        // Act
        var result1 = await _gateway.ChargeAsync("tok_visa", 10.00m);
        var result2 = await _gateway.ChargeAsync("tok_visa", 10.00m);

        // Assert
        Assert.AreNotEqual(result1.ChargeId, result2.ChargeId);
    }
}

[TestClass]
public sealed class PaymentGatewayRefundTests
{
    private readonly Payments.PaymentGateway _gateway;

    public PaymentGatewayRefundTests()
    {
        _gateway = new Payments.PaymentGateway();
    }

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessResult()
    {
        // Arrange
        var charge = await _gateway.ChargeAsync("tok_visa", 50.00m);

        // Act
        var refund = await _gateway.RefundAsync(charge.ChargeId);

        // Assert
        Assert.IsNotNull(refund);
        Assert.IsTrue(refund.Success);
        Assert.IsNotNull(refund.RefundId);
    }

    [TestMethod]
    public async Task RefundAsync_NullChargeId_ThrowsArgumentNullException()
    {
        // Act & Assert
        await Assert.ThrowsExactlyAsync<ArgumentNullException>(
            async () => await _gateway.RefundAsync(null!));
    }

    [TestMethod]
    public async Task RefundAsync_EmptyChargeId_ThrowsArgumentException()
    {
        // Act & Assert
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(string.Empty));
    }

    [TestMethod]
    public async Task RefundAsync_NonExistentChargeId_ReturnsFailureResult()
    {
        // Act
        var result = await _gateway.RefundAsync("ch_nonexistent_12345");

        // Assert
        Assert.IsNotNull(result);
        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task RefundAsync_AlreadyRefundedCharge_ReturnsFailure()
    {
        // Arrange
        var charge = await _gateway.ChargeAsync("tok_visa", 75.00m);
        await _gateway.RefundAsync(charge.ChargeId);

        // Act - attempt second refund
        var secondRefund = await _gateway.RefundAsync(charge.ChargeId);

        // Assert
        Assert.IsFalse(secondRefund.Success);
    }

    [TestMethod]
    public async Task RefundAsync_SuccessfulRefund_ReturnsUniqueRefundId()
    {
        // Arrange
        var charge1 = await _gateway.ChargeAsync("tok_visa", 20.00m);
        var charge2 = await _gateway.ChargeAsync("tok_visa", 30.00m);

        // Act
        var refund1 = await _gateway.RefundAsync(charge1.ChargeId);
        var refund2 = await _gateway.RefundAsync(charge2.ChargeId);

        // Assert
        Assert.AreNotEqual(refund1.RefundId, refund2.RefundId);
    }
}

